import sys

s = sys.stdin.read().split()[0]
n = len(s)
cnt = 0
for mask in range(1, 1 << n):
    bal = 0
    ok = True
    for i in range(n):
        if mask >> i & 1:
            bal += 1 if s[i] == '(' else -1
            if bal < 0:
                ok = False
                break
    if ok and bal == 0:
        cnt += 1
print(cnt % (10**9 + 7))

